//wiki.biligame.com/ys/%E5%A5%B9%E7%9A%84%E5%AE%AB%E6%AE%BF%E6%AD%A3%E5%9D%8D%E5%A1%8C%E5%90%91%E9%A3%8E%E9%9B%AA\"\u003e中文任务目录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%9B%BE%E4%B8%BA%E7%81%B5%E9%AD%82%E7%9A%84%E6%9C%A8%E8%88%9F\"\u003e「曾为灵魂的木舟」中文任务流程\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"7.1","major":7,"minor":1,"title":"第七章第三至四幕：白夜似梦初醒／往冥府的安魂歌","chapter":"第七章第3至4幕","sections":[{"id":"v7.1-s0","title":"第三幕：白夜似梦初醒","kind":"chapter","html":"\u003ch3\u003e觐见冰之女皇\u003c/h3\u003e\n\u003cp\u003e达达利亚为旅行者申请觐见。女仆长达妮卡先在餐厅试探旅行者的立场与身手，冬契军司令官、风仙薇斯纳及时制止了交锋。翌日，旅行者进入至冬宫，终于见到冰之女皇安娜丝塔夏。\u003c/p\u003e\n\u003cp\u003e女皇带旅行者查看第三降临者留下的封印。只有神之心能使它产生反应，她因而希望集齐由第三降临者遗骨制成的七颗神之心，打开封印。如今火神之心下落不明，里面的秘密仍无法探知。她也谈到自己的「慈爱」权能：在她看来，天理将爱人类的本能强加给魔神，使这份感情失去了自由；她拒绝依靠它治理至冬。由于自身记忆曾遭干预，她还每日用誊录棱晶保存记忆，借第三降临者的力量抵御世界规则的影响。\u003c/p\u003e\n\u003ch3\u003e生之印的征集\u003c/h3\u003e\n\u003cp\u003e皮耶罗利用「溯见之镜」，关联米提亚身上的死之印记与薇斯纳继承的生之权能，窥见两位执政的谈话。天理沉眠期间，天空岛仍会定期监测执政的行为。若娜瓦使触及禁限的研究者死亡，莱茵多特则赶在下一次监测前将他们复活，两人借此封锁至冬的技术，又避开擅杀人类的惩罚。研究者在反复死亡中丧失记忆，灵魂也逐渐受损。\u003c/p\u003e\n\u003cp\u003e薇斯纳的祖先曾受托保管少量生之权能。受桑多涅启发，她用这份力量提取与美好回忆相连的「生之印」，尝试汇聚众人的生命力抵抗死亡。提取的损耗很小，印记一旦破损，其中的回忆却可能消失。冬契军率先参与，北国银行随后向民众开放征集；旅行者与阿罗夏、奥黛塔、沃雅妮莎等人前往彩冰镇，将居民捐出的生之印带回。\u003c/p\u003e\n\u003ch3\u003e北国银行地下\u003c/h3\u003e\n\u003cp\u003e城中有人兜售延寿服务，众人循线发现，银行内部有人挪用生之印。旅行者与薇斯纳潜入金库，遇见正在调查的潘塔罗涅，又遭莱茵多特的失控实验体袭击。薇斯纳为保护印记透支力量，终于引来莱茵多特；她回收失窃的生之权能，将尚存的生之印归还原主。\u003c/p\u003e\n\u003cp\u003e女皇与潘塔罗涅早已料到，大规模征集会迫使藏在幕后的生之执政露面，因此顺势推动了消息传播。莱茵多特明确拒绝协助他们对抗若娜瓦。女皇随即以失踪的空间之执政阿斯莫代的情报为筹码，邀她七天后来至冬宫交换信息。薇斯纳失去大部分传承力量，女皇仍让银行归还那盏留有少量权能的明灯，替她保存了一份陪伴。\u003c/p\u003e\n","readingMinutes":2,"editions":{"epic":{"html":"\u003ch3\u003e觐见冰之女皇\u003c/h3\u003e\n\u003cp\u003e达达利亚替旅人申请觐见。餐厅里，女仆长达妮卡先来试探立场与身手，交锋尚未扩大，冬契军司令官、风仙薇斯纳便将两人制止。翌日，旅人走入至冬宫，终于见到冰之女皇安娜丝塔夏。\u003c/p\u003e\n\u003cp\u003e女皇带来客查看第三降临者留下的封印。封印只对神之心有所回应，她因此要集齐七颗由其遗骨制成的神之心，将它开启。火神之心如今不知所终，封印内的秘密仍未显露。\u003c/p\u003e\n\u003cp\u003e她也说起自己的慈爱权能。在她看来，天理将爱人的本能强加给魔神，使这份感情失去自由；她因而拒绝依此治理至冬。自己的记忆也曾遭人干预，她便每日以誊录棱晶留存，借第三降临者的力量，抵御世界规则的影响。\u003c/p\u003e\n\u003ch3\u003e生之印的征集\u003c/h3\u003e\n\u003cp\u003e皮耶罗借溯见之镜，将米提亚的死之印记与薇斯纳继承的生之权能相连，窥见两位执政的交谈。天理沉眠，天空岛仍定期监察执政。若娜瓦令触及禁限的研究者死去，莱茵多特再赶在监察之前将他们复活。她们以此封锁技术，也避过擅杀人类的惩罚。研究者却在生死反复之间，失去记忆，损伤灵魂。\u003c/p\u003e\n\u003cp\u003e薇斯纳的祖先曾受托保管少量生之权能。受桑多涅启发，她提取与美好回忆相连的生之印，要汇众人生命力，抵抗死亡。提取本身损耗甚微，印记若毁，其中的回忆却可能一同消失。\u003c/p\u003e\n\u003cp\u003e冬契军率先捐出印记，北国银行也向民间开放征集。旅人与阿罗夏、奥黛塔、沃雅妮莎前往彩冰镇，将居民捐出的生之印带回。\u003c/p\u003e\n\u003ch3\u003e北国银行地下\u003c/h3\u003e\n\u003cp\u003e城中传来兜售延寿服务的消息，众人循线查出，有人从银行挪用了生之印。旅人与薇斯纳潜入金库，遇见也在调查的潘塔罗涅，随后遭失控实验体袭击。\u003c/p\u003e\n\u003cp\u003e薇斯纳为护住印记透支力量，终于引来莱茵多特。她回收失窃的生之权能，将尚存的印记还给原主。女皇与潘塔罗涅早料到，大规模征集会使生之执政现身，才顺势推动消息传开。\u003c/p\u003e\n\u003cp\u003e莱茵多特拒绝相助。女皇便以失踪的空间之执政阿斯莫代的线索为筹码，邀她七日后入宫交换情报。薇斯纳失去大半传承，女皇仍让银行归还那盏留有少许权能的明灯，为她留下陪伴。\u003c/p\u003e\n","readingMinutes":2,"sources":"\u003cul\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://ys.mihoyo.com/main/m/news/detail/166253\"\u003e7.1 官方魔神任务与尾声开放公告\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%99%BD%E5%A4%9C%E4%BC%BC%E6%A2%A6%E5%88%9D%E9%86%92\"\u003e第三幕「白夜似梦初醒」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E6%BA%AF%E8%A7%81%E5%85%89%E5%BD%B1%E4%BA%A4%E7%BB%87\"\u003e溯见光影交织\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E6%98%9F%E7%81%AB%E4%BA%A4%E6%B1%87%E4%BA%8E%E5%86%BB%E5%8E%9F\"\u003e星火交汇于冻原\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BB%85%E6%AD%A4%E4%B8%80%E7%9D%80\"\u003e仅此一着\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C\"\u003e第四幕「往冥府的安魂歌」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E9%82%AA%E7%9C%BC%EF%BC%88%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C%EF%BC%89\"\u003e邪眼\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E8%A2%AB%E9%95%8C%E5%88%BB%E7%9A%84%E6%97%B6%E5%85%89\"\u003e被镌刻的时光\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BA%8E%E9%A5%AF%E5%88%AB%E4%B9%8B%E6%97%B6%E6%95%A3%E8%90%BD%E7%9A%84%E9%BB%91%E7%BE%BD\"\u003e于饯别之时散落的黑羽\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://allthings.how/genshin-impact-7-1-anomaly-epilogue-all-six-celestial-nail-quest-locations/\"\u003e「异象」六地任务与对话位置记录\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e本篇为史诗风格改写，情节依据本仓库 7.1 普通版，叙述止于该版本已公开的信息。\u003c/p\u003e\n\u003c/li\u003e\n\u003c/ul\u003e\n"}}},{"id":"v7.1-s1","title":"第四幕：往冥府的安魂歌","kind":"chapter","html":"\u003ch3\u003e邪眼与贤者的笔记\u003c/h3\u003e\n\u003cp\u003e阿蕾奇诺协助皮耶罗改良邪眼，希望借赤月残存的死亡力量迎战若娜瓦。实验引入了赤月的其他权能，导致幻觉与深渊侵蚀，旅行者及时净化污染，保住她的身体。阿蕾奇诺指出，即便消除副作用，现有增幅仍不足以对抗执政，研究必须寻找新的突破。\u003c/p\u003e\n\u003cp\u003e旅行者再次接触溯见之镜，意外看见皮耶罗年轻时与「贤者」海洛塔帝求学的记忆。当年海洛塔帝找到延续老师生命的办法，却在最后关头放弃，皮耶罗一直将此视为背叛。经在任执行官全票同意，众人解封贤者留下的笔记，才发现那项成果会让人承受无尽折磨；海洛塔帝曾称它为「不死祝福」，后来亲手改作「不死诅咒」。\u003c/p\u003e\n\u003cp\u003e笔记中还保存着海洛塔帝舍弃前的最后人性。皮耶罗进入那段可以交谈的记忆，与昔日同窗重新讨论邪眼。两人推导出以使用者的生命与灵魂换取瞬间爆发的方案，皮耶罗决定凭自身的不死诅咒承受代价，制造「愚人之眼」。旅行者也从这次交谈中追问血亲的来历。皮耶罗确认：当年自己从天空岛召来了派蒙，海洛塔帝则在同一时期召来了旅行者的血亲。\u003c/p\u003e\n\u003ch3\u003e两处战场\u003c/h3\u003e\n\u003cp\u003e约定的日子到来，女皇在至冬宫接待莱茵多特；旅行者与盟友则在曙光车站准备迎战。戴因斯雷布应皮耶罗之邀赶到，他也希望向降下不死诅咒的若娜瓦讨回旧债。\u003c/p\u003e\n\u003cp\u003e宫中的谈话触及女皇被抹去的过去。莱茵多特称，坎瑞亚人诞生于女皇与第三降临者融合的血脉；两人曾受白沙皇唆使打开深渊之门，女皇随后遭天理抹消。第三降临者以自己的生命交换她复活，并要求天理保护他们的后裔，又留下违约便会生效的诅咒。天理复活女皇，同时抹去了世间关于第三降临者的记忆。女皇据此推断，坎瑞亚灾变触发了诅咒，才使天理陷入沉眠。\u003c/p\u003e\n\u003cp\u003e车站的战斗很快陷入绝境。若娜瓦动用权能，众人一度落入死后世界。旅行者返回后继续拖住她，戴因斯雷布与携愚人之眼赶来的皮耶罗也加入牵制。若娜瓦发现复活迟迟没有发生，试图离开战场，却被三人拦下。\u003c/p\u003e\n\u003cp\u003e女皇已借六颗神之心增幅冰元素力，减慢至冬宫大厅内的时间流速。莱茵多特只觉茶会过去片刻，外界却已逼近天空岛的监测时刻。她错过约定的复活时间，若娜瓦擅自杀人的行为因而暴露，死亡权能被天空岛收回；莱茵多特则必须依指令救回众人。女皇拒绝让参战者成为弃子，也终于使对方承认自己遭到了算计。\u003c/p\u003e\n\u003ch3\u003e胜利与遗赠\u003c/h3\u003e\n\u003cp\u003e若娜瓦失去权能后仍有强大的战力，转而全力攻击众人。旅行者与戴因斯雷布为皮耶罗创造机会，愚人之眼最终命中若娜瓦，使她从战场消失。军械宫随后确认，封锁研究的死之诅咒已经解除，槲寄生计划得以继续。皮耶罗活了下来，精神与灵魂却受到严重损耗；他和戴因身上五百年前的不死诅咒仍然存在。\u003c/p\u003e\n\u003cp\u003e女皇召见并表彰参战者。战场之外，重伤的若娜瓦来到至冬的判罚之钉旁，取出亥珀波瑞亚人藏于影域的「地原胚质」，将它与巨钉融合。她要让自己临近死亡的感受，随她口中的「圣土化」降临整个提瓦特。\u003c/p\u003e\n","readingMinutes":3,"editions":{"epic":{"html":"\u003ch3\u003e邪眼与贤者的笔记\u003c/h3\u003e\n\u003cp\u003e阿蕾奇诺助皮耶罗改良邪眼，要借赤月残余的死亡力量，迎战若娜瓦。实验却引入赤月的其他权能，幻觉与深渊侵蚀随之而来。旅人及时净化污染，护住她的身体。即使副作用尽除，现有增幅仍不足以抗衡执政，研究还须向前。\u003c/p\u003e\n\u003cp\u003e旅人再触溯见之镜，意外看见皮耶罗年轻时与贤者海洛塔帝求学的记忆。当年，海洛塔帝找到延续老师生命的办法，却在最后关头放弃，皮耶罗一直视之为背叛。在任执行官全票同意后，贤者遗下的笔记终于解封：那项成果将使人承受无尽折磨。「不死祝福」的旧称，也被海洛塔帝亲手改作「不死诅咒」。\u003c/p\u003e\n\u003cp\u003e笔记还保存着贤者舍弃前的最后人性。皮耶罗走入可以交谈的记忆，再与同窗推演邪眼。两人找到以生命和灵魂，换取瞬间爆发的办法。皮耶罗决意凭自身的不死诅咒承受代价，造出愚人之眼。\u003c/p\u003e\n\u003cp\u003e旅人也由这场交谈，追问血亲的来历。皮耶罗确认，当年自己从天空岛召来派蒙，海洛塔帝则在同一时期召来了旅人的血亲。\u003c/p\u003e\n\u003ch3\u003e两处战场\u003c/h3\u003e\n\u003cp\u003e约定之日，女皇在宫中接待莱茵多特，旅人与盟友则在曙光车站备战。戴因斯雷布应皮耶罗相邀而至，也要向降下不死诅咒的若娜瓦，讨回旧债。\u003c/p\u003e\n\u003cp\u003e宫中的话语，触及女皇被抹去的过去。依莱茵多特所言，坎瑞亚人出自女皇与第三降临者融合的血脉。两人曾受白沙皇唆使，开启深渊之门，女皇随后遭天理抹消。第三降临者以自身生命换她复活，又要求天理庇护后裔，留下违约便会生效的诅咒。天理复活女皇，也抹去了世人关于第三降临者的记忆。\u003c/p\u003e\n\u003cp\u003e女皇据此推断，坎瑞亚的灾变触发了诅咒，才令天理陷入沉眠。\u003c/p\u003e\n\u003cp\u003e宫中仍在追叙旧史，车站已近绝境。若娜瓦动用权能，众人一度落入死后世界。旅人返回后继续拖住她，戴因斯雷布与携愚人之眼赶来的皮耶罗，也相继加入牵制。若娜瓦迟迟未见死者复生，想要脱离战场，却被三人阻住。\u003c/p\u003e\n\u003cp\u003e女皇早已借六颗神之心增幅冰元素力，让大厅中的时间缓缓流逝。莱茵多特只觉茶会过了片刻，宫外却已临近天空岛的监察时刻。她未能如约唤回死者，若娜瓦擅自降下的死亡，再也来不及掩去。天空岛收回死亡权能，又令莱茵多特救回众人。\u003c/p\u003e\n\u003ch3\u003e胜利与遗赠\u003c/h3\u003e\n\u003cp\u003e失去权能的若娜瓦仍然强大，转而向众人全力进攻。旅人与戴因斯雷布为皮耶罗争取机会，愚人之眼终于命中，若娜瓦的身影自战场消失。\u003c/p\u003e\n\u003cp\u003e军械宫传来确认，封锁研究的死之诅咒已除，槲寄生计划可以继续。皮耶罗活了下来，精神与灵魂却损耗严重。他与戴因背负五百年的不死诅咒，仍未解除。\u003c/p\u003e\n\u003cp\u003e女皇召见参战者，予以表彰。战场之外，重伤的若娜瓦来到至冬的判罚之钉旁。她取出亥珀波瑞亚人藏于影域的「地原胚质」，将它与巨钉融合，要让自己濒死的感受，随「圣土化」降临整个提瓦特。\u003c/p\u003e\n","readingMinutes":3,"sources":"\u003cul\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://ys.mihoyo.com/main/m/news/detail/166253\"\u003e7.1 官方魔神任务与尾声开放公告\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%99%BD%E5%A4%9C%E4%BC%BC%E6%A2%A6%E5%88%9D%E9%86%92\"\u003e第三幕「白夜似梦初醒」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E6%BA%AF%E8%A7%81%E5%85%89%E5%BD%B1%E4%BA%A4%E7%BB%87\"\u003e溯见光影交织\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E6%98%9F%E7%81%AB%E4%BA%A4%E6%B1%87%E4%BA%8E%E5%86%BB%E5%8E%9F\"\u003e星火交汇于冻原\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BB%85%E6%AD%A4%E4%B8%80%E7%9D%80\"\u003e仅此一着\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C\"\u003e第四幕「往冥府的安魂歌」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E9%82%AA%E7%9C%BC%EF%BC%88%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C%EF%BC%89\"\u003e邪眼\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E8%A2%AB%E9%95%8C%E5%88%BB%E7%9A%84%E6%97%B6%E5%85%89\"\u003e被镌刻的时光\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BA%8E%E9%A5%AF%E5%88%AB%E4%B9%8B%E6%97%B6%E6%95%A3%E8%90%BD%E7%9A%84%E9%BB%91%E7%BE%BD\"\u003e于饯别之时散落的黑羽\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://allthings.how/genshin-impact-7-1-anomaly-epilogue-all-six-celestial-nail-quest-locations/\"\u003e「异象」六地任务与对话位置记录\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e本篇为史诗风格改写，情节依据本仓库 7.1 普通版，叙述止于该版本已公开的信息。\u003c/p\u003e\n\u003c/li\u003e\n\u003c/ul\u003e\n"}}},{"id":"v7.1-s2","title":"尾声：异象","kind":"chapter","html":"\u003cp\u003e蒙德、璃月、稻妻、须弥、纳塔与至冬的六枚天钉同时亮起。旅行者曾在雪山与巨渊见过的巨钉，也在其中。光柱悬在各地天空，旅行者分别拜访阿贝多、魈、八重神子、迪希雅与坎蒂丝、玛薇卡和阿罗夏，查看异变。\u003c/p\u003e\n\u003cp\u003e阿贝多开始观察雪山天钉对周围环境的影响；魈奉钟离之命监视层岩巨渊；八重神子来到鹤观调查天光。沙漠中的迪希雅与坎蒂丝协助守望村落，玛薇卡留意纳塔上空，阿罗夏则在白桦雪葬附近观察判罚之钉的光芒与异响。各地都已采取行动，异变的后果仍未明朗。\u003c/p\u003e\n","readingMinutes":1,"editions":{"epic":{"html":"\u003cp\u003e蒙德、璃月、稻妻、须弥、纳塔与至冬，六枚天钉同时亮起。雪山山巅与巨渊地底，旅人曾见过的巨钉也在其中。光柱高悬六国，旅人循光走访故友，查探异变。\u003c/p\u003e\n\u003cp\u003e阿贝多观察雪山天钉与周遭环境，魈奉钟离之命守望层岩巨渊，八重神子赴鹤观调查天光。沙漠中，迪希雅与坎蒂丝协助守护村落；玛薇卡留意纳塔上空，阿罗夏则在白桦雪葬，察看判罚之钉的光与异响。\u003c/p\u003e\n\u003cp\u003e各地的守望已经开始，光柱仍悬在天际。异变的后果，仍待查明。\u003c/p\u003e\n","readingMinutes":1,"sources":"\u003cul\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://ys.mihoyo.com/main/m/news/detail/166253\"\u003e7.1 官方魔神任务与尾声开放公告\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%99%BD%E5%A4%9C%E4%BC%BC%E6%A2%A6%E5%88%9D%E9%86%92\"\u003e第三幕「白夜似梦初醒」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E6%BA%AF%E8%A7%81%E5%85%89%E5%BD%B1%E4%BA%A4%E7%BB%87\"\u003e溯见光影交织\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E6%98%9F%E7%81%AB%E4%BA%A4%E6%B1%87%E4%BA%8E%E5%86%BB%E5%8E%9F\"\u003e星火交汇于冻原\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BB%85%E6%AD%A4%E4%B8%80%E7%9D%80\"\u003e仅此一着\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C\"\u003e第四幕「往冥府的安魂歌」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E9%82%AA%E7%9C%BC%EF%BC%88%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C%EF%BC%89\"\u003e邪眼\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E8%A2%AB%E9%95%8C%E5%88%BB%E7%9A%84%E6%97%B6%E5%85%89\"\u003e被镌刻的时光\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BA%8E%E9%A5%AF%E5%88%AB%E4%B9%8B%E6%97%B6%E6%95%A3%E8%90%BD%E7%9A%84%E9%BB%91%E7%BE%BD\"\u003e于饯别之时散落的黑羽\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://allthings.how/genshin-impact-7-1-anomaly-epilogue-all-six-celestial-nail-quest-locations/\"\u003e「异象」六地任务与对话位置记录\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e本篇为史诗风格改写，情节依据本仓库 7.1 普通版，叙述止于该版本已公开的信息。\u003c/p\u003e\n\u003c/li\u003e\n\u003c/ul\u003e\n"}}},{"id":"v7.1-s3","title":"此刻悬而未决","kind":"question","html":"\u003cul\u003e\n\u003cli\u003e第三降临者的封印里留下了什么？失踪的火神之心在哪里？\u003c/li\u003e\n\u003cli\u003e血亲为何曾在天空岛，又为何响应海洛塔帝的召唤？\u003c/li\u003e\n\u003cli\u003e若娜瓦留下的地原胚质会引发什么？女皇的反抗将如何继续？\u003c/li\u003e\n\u003c/ul\u003e\n","readingMinutes":1,"editions":{"epic":{"html":"\u003cp\u003e第三降临者的封印中，究竟留有什么？失踪的火神之心，如今又在何方？\u003c/p\u003e\n\u003cp\u003e血亲为何曾在天空岛，又为何回应海洛塔帝的召唤？\u003c/p\u003e\n\u003cp\u003e若娜瓦遗下的地原胚质，将带来怎样的异变？冰之女皇的反抗，还将如何继续？\u003c/p\u003e\n","readingMinutes":1,"sources":"\u003cul\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://ys.mihoyo.com/main/m/news/detail/166253\"\u003e7.1 官方魔神任务与尾声开放公告\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%99%BD%E5%A4%9C%E4%BC%BC%E6%A2%A6%E5%88%9D%E9%86%92\"\u003e第三幕「白夜似梦初醒」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E6%BA%AF%E8%A7%81%E5%85%89%E5%BD%B1%E4%BA%A4%E7%BB%87\"\u003e溯见光影交织\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E6%98%9F%E7%81%AB%E4%BA%A4%E6%B1%87%E4%BA%8E%E5%86%BB%E5%8E%9F\"\u003e星火交汇于冻原\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BB%85%E6%AD%A4%E4%B8%80%E7%9D%80\"\u003e仅此一着\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C\"\u003e第四幕「往冥府的安魂歌」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E9%82%AA%E7%9C%BC%EF%BC%88%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C%EF%BC%89\"\u003e邪眼\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E8%A2%AB%E9%95%8C%E5%88%BB%E7%9A%84%E6%97%B6%E5%85%89\"\u003e被镌刻的时光\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BA%8E%E9%A5%AF%E5%88%AB%E4%B9%8B%E6%97%B6%E6%95%A3%E8%90%BD%E7%9A%84%E9%BB%91%E7%BE%BD\"\u003e于饯别之时散落的黑羽\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e\u003ca href=\"https://allthings.how/genshin-impact-7-1-anomaly-epilogue-all-six-celestial-nail-quest-locations/\"\u003e「异象」六地任务与对话位置记录\u003c/a\u003e\u003c/p\u003e\n\u003c/li\u003e\n\u003cli\u003e\n\u003cp\u003e本篇为史诗风格改写，情节依据本仓库 7.1 普通版，叙述止于该版本已公开的信息。\u003c/p\u003e\n\u003c/li\u003e\n\u003c/ul\u003e\n"}}}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://ys.mihoyo.com/main/m/news/detail/166253\"\u003e7.1 官方魔神任务与尾声开放公告\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%99%BD%E5%A4%9C%E4%BC%BC%E6%A2%A6%E5%88%9D%E9%86%92\"\u003e第三幕「白夜似梦初醒」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E6%BA%AF%E8%A7%81%E5%85%89%E5%BD%B1%E4%BA%A4%E7%BB%87\"\u003e溯见光影交织\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E6%98%9F%E7%81%AB%E4%BA%A4%E6%B1%87%E4%BA%8E%E5%86%BB%E5%8E%9F\"\u003e星火交汇于冻原\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BB%85%E6%AD%A4%E4%B8%80%E7%9D%80\"\u003e仅此一着\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C\"\u003e第四幕「往冥府的安魂歌」任务目录\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E9%82%AA%E7%9C%BC%EF%BC%88%E5%BE%80%E5%86%A5%E5%BA%9C%E7%9A%84%E5%AE%89%E9%AD%82%E6%AD%8C%EF%BC%89\"\u003e邪眼\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E8%A2%AB%E9%95%8C%E5%88%BB%E7%9A%84%E6%97%B6%E5%85%89\"\u003e被镌刻的时光\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E4%BA%8E%E9%A5%AF%E5%88%AB%E4%B9%8B%E6%97%B6%E6%95%A3%E8%90%BD%E7%9A%84%E9%BB%91%E7%BE%BD\"\u003e于饯别之时散落的黑羽\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://allthings.how/genshin-impact-7-1-anomaly-epilogue-all-six-celestial-nail-quest-locations/\"\u003e「异象」六地任务与对话位置记录\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"}]};
